import { cache } from 'react';
import { revalidateTag } from 'next/cache';
import { getAllProducts } from '../lib/db';

// Cache the products data with a "products" tag
const getCachedProducts = cache(async () => {
  'use cache';
  return getAllProducts();
});

// Server action to invalidate the cache
async function invalidateCache() {
  'use server';
  revalidateTag('products');
  return { success: true };
}

// Child component that fetches product data
async function ProductList() {
  const products = await getCachedProducts();

  return (
    <div>
      <h2>Products</h2>
      <ul>
        {products.map((product) => (
          <li key={product.id}>
            {product.name} - ${product.price}
          </li>
        ))}
      </ul>
    </div>
  );
}

export default function Page() {
  return (
    <div>
      <h1>Home</h1>
      <ProductList />

      <form action={invalidateCache}>
        <button type="submit">Refresh Products</button>
      </form>
    </div>
  );
}

